'use strict';

const fs = require('fs');
const path = require('path');

const url = String(process.env.GAME_SERVER_URL || '')
  .trim()
  .replace(/\/$/, '');

const out = path.join(__dirname, '..', 'public', 'config.js');
const body =
  '/* generated by scripts/write-netlify-config.js — do not edit by hand on Netlify */\n' +
  `window.GAME_SERVER_URL = ${JSON.stringify(url)};\n`;

fs.writeFileSync(out, body, 'utf8');
console.log(
  'Wrote',
  out,
  '→ GAME_SERVER_URL=',
  url || '(empty — same-origin / set Netlify env GAME_SERVER_URL to your Render URL)'
);
